'use client';

// Vendored from MerchFlow Charts components/web/SummarySection.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { gms } from '@/lib/merch-flow-report/brand/tokens';
import { units, usd, compactUsd, percent } from '@/lib/merch-flow-report/format';
import { totalGross, totalUnits, type Product, type TourReport } from '@/lib/merch-flow-report/report/types';
import {
  keyFigures,
  scorecard,
  perHeadValue,
  titleCase,
  flagShows,
  inferTourStart,
} from '@/lib/merch-flow-report/report/derive';

/**
 * Tour Summary.
 *
 * "Key figures" are factual statements with a number attached — never
 * interpretation. Each one is verifiable from the sections below it.
 */
export function SummarySection({
  report,
  imageUrls,
  onSelect,
}: {
  report: TourReport;
  imageUrls: Record<string, string>;
  onSelect: (product: Product) => void;
}) {
  const gross = totalGross(report.shows);
  const perHead = perHeadValue(report);
  const figures = keyFigures(report);
  const top5 = scorecard(report.products).slice(0, 5);

  // Best and worst exclude the pre-leg one-offs: two isolated dates with tiny
  // grosses would otherwise fill the whole "softest" list and say nothing
  // about the tour.
  const flagged = flagShows(report.shows, inferTourStart(report.shows));
  const onLeg = flagged.filter((s) => s.flag !== 'outsideRange');
  const excluded = flagged.length - onLeg.length;

  const ranked = [...(onLeg.length ? onLeg : flagged)].sort((a, b) => b.grossUsd - a.grossUsd);
  const maxGross = ranked[0]?.grossUsd ?? 1;
  const strongest = ranked.slice(0, 5);
  const softest = ranked.slice(-5).reverse();

  const kpis = [
    { label: 'Tour gross', value: compactUsd(gross), note: `${report.shows.length} shows` },
    {
      label: 'Units sold',
      value: units(totalUnits(report.products)),
      note: `${report.products.length} products`,
    },
    {
      label: 'Attendance',
      value: report.attendance ? units(report.attendance) : '—',
      note: 'Entered in the wizard',
    },
    {
      label: 'Average per head',
      value: usd(perHead, 2),
      note:
        report.options?.perHead === 'grossOverAttendance'
          ? 'Gross ÷ attendance'
          : `Mean of all ${report.shows.length} shows`,
    },
    {
      label: 'Average per show',
      value: compactUsd(report.shows.length ? gross / report.shows.length : 0),
      note: ranked[0] ? `Best: ${titleCase(ranked[0].city)}` : '',
    },
  ];

  return (
    <div>
      <dl data-tour="mf-kpis" className="grid grid-cols-2 gap-2.5 sm:grid-cols-3 lg:grid-cols-5">
        {kpis.map((kpi) => (
          <div
            key={kpi.label}
            className="rounded px-3 pb-3 pt-2.5"
            style={{ background: gms.surface, borderTop: `2px solid ${gms.red}` }}
          >
            <dt
              className="text-[11px] font-bold uppercase tracking-[0.1em]"
              style={{ color: gms.slate }}
            >
              {kpi.label}
            </dt>
            <dd className="tnum mt-2 text-[22px] font-extrabold leading-none text-ink sm:text-[26px]">
              {kpi.value}
            </dd>
            <dd className="mt-2 text-[12px]" style={{ color: gms.slate }}>
              {kpi.note}
            </dd>
          </div>
        ))}
      </dl>

      <div className="mt-7 grid gap-7 lg:grid-cols-3">
        {figures.length > 0 && (
          <section data-tour="mf-figures">
            <h3
              className="border-b pb-1.5 text-[11px] font-bold uppercase tracking-[0.12em]"
              style={{ color: gms.red, borderColor: gms.border }}
            >
              Key figures
            </h3>
            <ul>
              {figures.map((figure) => (
                <li
                  key={figure.stat + figure.text}
                  className="flex gap-3 border-b py-3"
                  style={{ borderColor: '#F0F0F0' }}
                >
                  <span
                    className="tnum shrink-0 text-[22px] font-extrabold leading-none"
                    style={{ color: gms.red }}
                  >
                    {figure.stat}
                  </span>
                  <span className="text-[13px] leading-snug text-ink">{figure.text}</span>
                </li>
              ))}
            </ul>
          </section>
        )}

        <section>
          <h3
            className="border-b pb-1.5 text-[11px] font-bold uppercase tracking-[0.12em]"
            style={{ color: gms.red, borderColor: gms.border }}
          >
            Top five products · units
          </h3>
          <ul>
            {top5.map((product) => (
              <li key={product.sku} style={{ borderColor: '#F0F0F0' }} className="border-b">
                <button
                  onClick={() => onSelect(product)}
                  className="-mx-1.5 flex w-[calc(100%+0.75rem)] items-center gap-2.5 rounded px-1.5 py-2 text-left transition-colors hover:bg-app"
                >
                  <span
                    className="flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded border bg-white"
                    style={{ borderColor: gms.border }}
                  >
                    {imageUrls[product.sku] ? (
                      /* eslint-disable-next-line @next/next/no-img-element */
                      <img
                        src={imageUrls[product.sku]}
                        alt=""
                        className="max-h-full max-w-full object-contain"
                      />
                    ) : (
                      <span className="text-[12px]" style={{ color: gms.slate }}>
                        <span aria-hidden="true">—</span>
                        <span className="sr-only">No image</span>
                      </span>
                    )}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[13px] font-semibold text-ink">
                      {product.displayName ?? product.name}
                    </span>
                    <span className="block text-[12px]" style={{ color: gms.slate }}>
                      {percent(product.shareOfGross, 1)} of gross
                      {report.attendance > 0 &&
                        ` · Ratio 1 in ${Math.round(report.attendance / product.unitsSold)}`}
                    </span>
                  </span>
                  <span className="tnum shrink-0 text-[13px] font-bold text-ink">
                    {units(product.unitsSold)}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </section>

        <section>
          {[
            { title: 'Strongest shows · gross', rows: strongest },
            { title: 'Softest shows · gross', rows: softest },
          ].map((block) => (
            <div key={block.title} className="mb-5">
              <h3
                className="border-b pb-1.5 text-[11px] font-bold uppercase tracking-[0.12em]"
                style={{ color: gms.red, borderColor: gms.border }}
              >
                {block.title}
              </h3>
              <ul>
                {block.rows.map((show) => (
                  <li
                    key={`${show.date}-${show.city}`}
                    className="flex items-center gap-2 border-b py-1.5"
                    style={{ borderColor: '#F0F0F0' }}
                  >
                    <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-ink">
                      {titleCase(show.city)}
                    </span>
                    <span className="relative hidden h-2.5 w-20 shrink-0 sm:block">
                      <span
                        className="absolute inset-0 rounded"
                        style={{ background: '#E4E6E9' }}
                      />
                      <span
                        className="absolute left-0 top-0 h-full rounded"
                        style={{
                          width: `${(show.grossUsd / maxGross) * 100}%`,
                          background: block.rows === strongest ? gms.red : '#C9CCD1',
                        }}
                      />
                    </span>
                    <span className="tnum w-14 shrink-0 text-right text-[12px] font-semibold text-ink">
                      {compactUsd(show.grossUsd)}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
          {excluded > 0 && (
            <p className="text-[12px]" style={{ color: gms.slate }}>
              Excludes {excluded} pre-tour one-off{excluded === 1 ? '' : 's'}.
            </p>
          )}
        </section>
      </div>
    </div>
  );
}
